using System.Data;
using Microsoft.EntityFrameworkCore;

static async Task SendStatementsAsync(
    BankDb db, IMailer mailer, CancellationToken ct)
{
    // One snapshot "for safety", held while every email goes out
    await using var tx = await db.Database.BeginTransactionAsync(
        IsolationLevel.RepeatableRead, ct);
    var accounts = await db.Accounts.AsNoTracking().ToListAsync(ct);
    foreach (var account in accounts)
        await mailer.SendStatementAsync(account, ct); // slow, external
    await tx.CommitAsync(ct); // Test: 100,000 dead rows not removable
}

using Microsoft.EntityFrameworkCore;

static async Task SendStatementsAsync(
    BankDb db, IMailer mailer, CancellationToken ct)
{
    // One statement, one snapshot, released once the rows have arrived
    var accounts = await db.Accounts.AsNoTracking().ToListAsync(ct);
    foreach (var account in accounts)
        await mailer.SendStatementAsync(account, ct); // no transaction open
    // Test: backend_xmin stayed null and VACUUM removed every dead row
}

